INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Considerando a jurisprudência consolidada do STF a respeito da inviolabilidade de domicílio, é lícito o ingresso forçado de autoridade policial em residência, sem mandado judicial e durante o período noturno, caso exista fundada suspeita – amparada em elementos prévios e objetivos – de que ocorre, no interior do imóvel, situação de flagrante delito, não sendo a mera fuga do suspeito para o interior da residência, por si só, justificativa legítima suficiente para a dispensa da ordem judicial.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva está correta. O STF, em repercussão geral (Tema 280), firmou que o ingresso forçado em domicílio exige fundadas razões (justa causa) que apontem para flagrante delito. Adicionalmente, o Tribunal Superior tem decidido reiteradamente (como em casos criminais recentes) que a simples atitude suspeita consistente na fuga isolada do indivíduo para o interior de sua residência não configura justa causa suficiente para mitigar a inviolabilidade domiciliar, tornando ilícitas as provas ali colhidas ausentes outros elementos robustos preliminares.","difficulty":"dificil","tags":["Direitos Individuais","Inviolabilidade de Domicílio","STF"]}'::jsonb, 'draft', 'v49wua_0', 0),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Acerca do compartilhamento de dados sigilosos e limites dos direitos individuais, o Supremo Tribunal Federal sedimentou entendimento favorável, com repercussão geral reconhecida, quanto à validade do repasse de informações e de dados bancários e fiscais sigilosos diretamente pela Receita Federal ao Ministério Público, para fins de persecução penal, desde que precedida, inexoravelmente, de ampla e restritiva prévia ordem judicial deferida pelo juízo criminal competente.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva está errada. O STF (Temas 990 e 225) estabeleceu tese de que é totalmente lícito e constitucional o compartilhamento integral dos relatórios de inteligência financeira da UIF (antigo COAF) e da íntegra do procedimento fiscalizatório da Receita Federal (que define o lançamento do tributo) diretamente com os órgãos de persecução penal do Ministério Público, independentemente de emissão de qualquer prévia ordem ou reserva de jurisdição por parte de magistrados.","difficulty":"dificil","tags":["Direitos Individuais","Sigilo Bancário e Fiscal","Compartilhamento de Dados"]}'::jsonb, 'draft', 'jj37vv_1', 1),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A respeito das ações constitucionais garantidoras de direitos individuais e difusos, a jurisprudência dominante consigna que qualquer cidadão detém legitimidade para ajuizar ação popular com vistas à anulação de ato lesivo à moralidade administrativa, mesmo nas hipóteses em que, concretamente, se demonstre a total inexistência de prejuízo material ou lesividade financeira efetiva ao erário, consubstanciando proteção autônoma à probidade.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva está correta. É magistério seguro na compreensão do STF e do STJ que a Ação Popular possui o escopo primário de defender não apenas o erário estrito, mas o patrimônio imaterial da administração republicana. Assim, a lesão pressuposta à moralidade administrativa (probidade) é suficiente para legitimar o processamento e provimento da ação protetiva, independentemente de se auferir com exatidão ou não um dano patrimonial material, que figura de maneira reflexa ou desnecessária para a anulação.","difficulty":"dificil","tags":["Garantias Constitucionais","Ação Popular","Moralidade Administrativa"]}'::jsonb, 'draft', 'x6tvy2_2', 2),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"O primado do tribunal do júri carrega assento nos direitos e garantias fundamentais previstos na Constituição Federal. Nesse liame material, se um réu foi definitivamente absolvido por clemência (quesito genérico absolutório) e, subsequentemente, o Ministério Público recorre em via de apelação sob o argumento de manifesta contrariedade às provas dos autos judiciais, a cassação respectiva dessa sentença por Tribunal de Justiça e a remessa a novo júri configurará incontestável ofensa ao postulado absoluto da soberania dos veredictos.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva está errada. Conforme interpretação constitucional consolidada pacientemente pelo STF no Tema de Repercussão Geral 1.087, a sistemática da absolvição baseada em quesito genérico (clemência) submete-se também, na eventualidade de ser flagrantemente manifesta em desconexão técnica das evidências, a possibilidade de único recurso de apelação ministerial por contrariedade à prova dos autos (artigo 593, inciso III, ´d´, CPP). Determinar a condução a um novo júri não fere o princípio em tela da soberania dos veredictos, o qual não comporta conotação absoluta.","difficulty":"dificil","tags":["Tribunal do Júri","Soberania dos Veredictos","Direitos Individuais","Apelação"]}'::jsonb, 'draft', 'hmzhsk_3', 3),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A prerrogativa inatingível do habeas corpus não é concebida a todo e qualquer ato processual constritor. Diante das estritas balizas constitucionais, segundo o Supremo Tribunal Federal, reveste-se de plena cabibilidade a impetração do remédio heroico no intuito de questionar e anular o próprio mérito material embasador em que se fundam punições e constrições disciplinares exclusivamente de cunho administrativo advindas perante servidores do regime público militar ativo.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva está errada. O artigo 142, parágrafo 2º da Carta Maior assevera expressamente proscrição textual que ''não caberá habeas corpus em relação a punições disciplinares militares''. O STF possui jurisprudência reiterada afirmando que, embora seja possível utilizar a referida via heroica apenas para análise e aferimento de questões sobre regularidade formal da custódia punitiva – tais como hierarquia, tipicidade legal extrínseca e competência punitiva da autoridade – jamais se tolera a via sumaríssima do habeas corpus para a ingerência no núcleo de ''mérito'' ou na razoabilidade material em que fundam-se as punições e o regime militar.","difficulty":"dificil","tags":["Habeas Corpus","Militares","Punição Disciplinar","Garantias Constitucionais"]}'::jsonb, 'draft', '1zufli_4', 4),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Conquanto a Constituição Federal de 1988 resguarde intensamente a extradição, delineando vedação imperativa para que brasileiros natos jamais venham a ser extraditados, faculta-se incondicionalmente ao brasileiro meramente naturalizado a possibilidade da referida devolução em decorrência de prévia deliberação da competência do Supremo. Nesse caso atípico de brasileiro naturalizado, a extradição dar-se-á validamente frente a eventual cometimento do delito pernicioso de tráfico de entorpecentes em data comprovadamente ocorrida muito após a formal concessão naturalizatória perante os órgãos da pátria.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva está correta em seu cerne interpretativo. O artigo 5º, inciso LI, estipula terminantemente que o brasileiro nato nunca será extraditado, constituindo direito fundamental insusceptível. No entanto, o naturalizado passará pela moldura de duas eventuais exceções flagrantes onde ocorrerá a devolução: a primeira concernente ao crime comum com a devida perpetração ''antes da naturalização''; e, a segunda, se atinente a sua participação direta ou conexa quanto ao execrável crime tipificado de ''tráfico ilícito de entorpecentes e drogas afins'', caso fortuito em que pouco importa a temporalidade prévia ou posterior à concessão de naturalização brasileira na dicção hermenêutica da lei.","difficulty":"dificil","tags":["Nacionalidade","Extradição","Tráfico de Drogas","Direitos Fundamentais"]}'::jsonb, 'draft', 'ab0rzs_5', 5),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Invocação amparada no princípio e direito fundamental afeto à escusa de consciência, esculpida na Constituição expressamente no corpo do art. 5º, exime legitimamente o cidadão livre em relação à obrigatoriedade atinente de cumprir imposições civis estatais compulsórias generalizadas quando em forte antagonismo de convicção. Com efeito, a pura e elementar recusa peremptória a determinada atividade forçosa leva invariavelmente, por via direta administrativa, como consequência restritiva punitiva originária inafastável, à drástica perda em caráter irreversível dos direitos políticos do postulante.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva contém duplo equívoco sistemático e está destituída de base. Consoante apregoa o modelo delineado por meio do comando do art. 5º, VIII, da CF, as convicções íntimas não privam direitos diretos, a menos que o cidadão se oponha não apenas e conjuntamente ao imperativo afeto à obrigação a todos consubstanciada imposta originariamente, mas também se exima reiteradamente de cumprir uma expressa e predeterminada ''prestação alternativa subsidiária'' delineada especificamente em lei secundária. Só neste caso configurado é que passaria a suportar as retaliações de ordem do direito político, retaliações essas na modalidade técnica de rigorosa ''perda'' dos direitos segundo o ditame jurisprudencial amplamente consagrado afeto ao inciso dante o art. 15 da Magna Carta.","difficulty":"dificil","tags":["Escusa de Consciência","Direitos Políticos","Direitos Individuais","Obrigações a todos imposta"]}'::jsonb, 'draft', '5er2xw_6', 6),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Apesar do primado constitucional conferido ao princípio universal do juiz natural garantindo à figura persecutória do preso as instâncias e foros corretos no ordenamento, a Magna Carta impôs que a lei processual repressiva só retroagirá eximiamente para o beneficiamento de modo equânime em favor do infrator. No entanto, se deflagrada posteriormente ao trânsito em julgado de determinada sentença a superveniência descriminalizadora ou suavizadora legal penal mais branda (lex mitior), esta referida inovação de ordem não logrará transpassar a coisa julgada do império da anterior sentença no que tange especificamente aos limitados campos secundários atinentes aos efeitos extramatrimoniais cíveis ou secundários processuais punitivos advindos.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva está correta de acordo com as sistemáticas penalistas da ordem constitucional. Decorrente diretamente das garantias explícitas advindas ex vi art. 5º, inciso XL, a retroatividade afeta irrevogavelmente as imposições da lex gravior. No caso superveniente advindo de ''abolitio criminis'', que revoga e cancela as estruturas formais processuais atinentes ao estigma principal punitivo estrito senso (ou sua reavaliação branda), não serão em absoluto dizimados nem extintos os devidos trâmites e reflexos atrelados originariamente aos imperiosos ''efeitos subjacentes meramente cíveis'' vinculativos perante o dano outrora impingido pela sentença transcorrida com coisa julgada.","difficulty":"dificil","tags":["Retroatividade","Coisa Julgada","Abolitio Criminis","Direitos Individuais"]}'::jsonb, 'draft', '3ux7zm_7', 7),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"No cômputo da proteção à liberdade associativa regida pelos cânones dos direitos individuais delineados pelo texto constitucional, determina-se que a intrínseca desconstituição coercitiva das agremiações e associações ou a referida e correspondente suspensão administrativa liminar peremptória de suas bases primárias organizacionais podem em todo o espectro suceder validamente mediante simples determinação administrativa dos órgãos federativos caso flagrantemente subvertam as premissas da constituição e da democracia, desde que ocorra estrito direito a procedimento administrativo subsequente.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva é completamente errada sob a estrita ótica de proteção sistêmica afeta ao art. 5º, inciso XIX, da CF. Segundo o imperativo categórico normativo constitucional de liberdade de agregação, é ressaltado explicitamente como postulado basilar de cunho restritivo máximo que os agrupamentos ou as associações ''Lado outro, somente poderão efetivamente e forçosamente ser compulsoriamente dissolvidos atípica e restritamente por força exclusiva pertinente à inafastável ordem jurídica na moldura de estrita decisão judicial – exigindo-se expressamente o inarredável trânsito em julgado prévio formal para o campo da dissolução –, eximidas determinações administrativas meramente procedimentais ou de poder executivo ordinário''.","difficulty":"dificil","tags":["Liberdade de Associação","Dissolução Compulsória","Direitos Individuais"]}'::jsonb, 'draft', 's4gu2q_8', 8),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Com a incorporação formal efetuada atinente à novata normatização materializada referente ao balizado inciso contido por intermédio da Emenda Constitucional n.º 115, agregou-se de forma expressa o basilar direito e o amparo voltado à ampla proteção dos dados sensíveis e pessoais, inserido especificamente e umbilicalmente dentre a gama do sagrado catálogo englobando todos os magnos direitos individuais em primado perante o texto da Carta de Outubro, consolidando-se no cenário prático que isso alçou ao patamar também as normativas legais relativas à devida abrangência inserida aos mais díspares meios organizacionais essencialmente digitais.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva está rigorosamente correta. O recém erigido texto por intermédio constitucional e normatividade efetuada por decorrência do advento impulsionado da Emenda n.º 115 trouxe a inovação inarredável materializando ao acréscimo específico redacional correspondendo categoricamente no novel permissivo do inciso LXXIX ao artigo 5º no seguinte aspecto: ''é pontuado com evidência o inquestionável resguardo assegurado relativo e afeto à devida proteção aos chamados dados pessoais, em toda sorte também perante aqueles efetivamente coligidos em bases e nos moldes dos atuais universos e suportes de ordem digital''. Trata-se de garantia individual plenamente constituída e de moderníssima inserção.","difficulty":"media","tags":["Proteção de Dados Pessoais","Emenda Constitucional 115","Meios Digitais","Inovação Constitucional"]}'::jsonb, 'draft', '8ssf72_9', 9);